import os
def transform(g):
    import collections
    H,W=len(g),len(g[0])
    comp=[[ -1]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if comp[i][j]==-1:
                c=g[i][j]; cid=len(comps); q=collections.deque([(i,j)]); comp[i][j]=cid; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and comp[ny][nx]==-1 and g[ny][nx]==c:
                            comp[ny][nx]=cid; q.append((ny,nx))
                comps.append(cells)
    out=[row[:] for row in g]
    for cid,cells in enumerate(comps):
        c=g[cells[0][0]][cells[0][1]]
        touches=any(y==0 or y==H-1 or x==0 or x==W-1 for y,x in cells)
        if touches: continue
        nb=set()
        for y,x in cells:
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]!=c: nb.add(g[ny][nx])
        if len(nb)==1:
            fill=7 if len(cells)%2==1 else 2
            for y,x in cells: out[y][x]=fill
    return out

